INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('12bea220-594b-4e61-952f-98f4fdca8436', '150f78d3-019b-40c0-962e-a83576309ea5', 1, 'O Centro de Gravidade', NULL, '{"intro": "O cora\u00e7\u00e3o \u00e9 o centro de comando de todas as nossas decis\u00f5es.", "prayer": "Pe\u00e7a para ancorar seu cora\u00e7\u00e3o na Verdade.", "practice": "Observe para onde o seu pensamento foge quando voc\u00ea est\u00e1 livre.", "reflection": "Onde est\u00e1 o teu tesouro, a\u00ed estar\u00e1 o teu cora\u00e7\u00e3o.", "journal_prompt": "O que ocupa o trono do seu cora\u00e7\u00e3o hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;